// ─── File: JwtValidationDemo.java ───
package com.bank.jwtval;

import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.Base64;
import java.util.Map;
import java.util.logging.*;

public class JwtValidationDemo {
    private static final Logger log = Logger.getLogger(JwtValidationDemo.class.getName());
    static final String BANK_NAME = "National Bank of India";

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        String secret = "national-bank-validation-secret-256bit";
        JwtValidator validator = new JwtValidator(secret, "national-bank", 30);

        long exp = Instant.now().getEpochSecond() + 900;
        String good = mint(secret, "rajesh", "national-bank", exp);
        log.info(() -> "Good token claims: " + validator.validate(good));

        // Tampered payload
        try {
            String[] p = good.split("\\.");
            String evil = Base64.getUrlEncoder().withoutPadding()
                .encodeToString(("rajesh|ADMIN|national-bank|" + exp).getBytes(StandardCharsets.UTF_8));
            validator.validate(p[0] + "." + evil + "." + p[2]);
        } catch (TokenValidationException e) {
            log.severe("Rejected tampered token: " + e.getMessage());
        }

        // Expired
        try {
            validator.validate(mint(secret, "rajesh", "national-bank", Instant.now().getEpochSecond() - 100));
        } catch (TokenValidationException e) {
            log.severe("Rejected expired token: " + e.getMessage());
        }

        // Wrong issuer
        try {
            validator.validate(mint(secret, "rajesh", "fake-bank", exp));
        } catch (TokenValidationException e) {
            log.severe("Rejected wrong-issuer token: " + e.getMessage());
        }

        log.warning("Payload is readable by anyone -> never store PIN/balance/card in it");
    }

    // Helper that mints "sub|role|iss|exp".signature tokens for the demo.
    static String mint(String secret, String sub, String iss, long exp) {
        String payload = sub + "|CUSTOMER|" + iss + "|" + exp;
        String p64 = Base64.getUrlEncoder().withoutPadding()
            .encodeToString(payload.getBytes(StandardCharsets.UTF_8));
        String h64 = Base64.getUrlEncoder().withoutPadding()
            .encodeToString("{\"alg\":\"HS256\"}".getBytes(StandardCharsets.UTF_8));
        return h64 + "." + p64 + "." + JwtValidator.hmac(secret, h64 + "." + p64);
    }
}

